<script setup>
import { onMounted, ref } from 'vue';
import LoadingBlock from '../components/LoadingBlock.vue'; import PageHeading from '../components/PageHeading.vue'; import { api, apiMessage } from '../lib/api';
const year=ref(String(new Date().getFullYear())), period=ref('q1'), data=ref(null), loading=ref(false), error=ref('');
const percent=(v)=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`;
const load=async()=>{loading.value=true;error.value='';try{data.value=(await api.get('/workplan-performance/state/rankings',{params:{year:year.value,period:period.value}})).data.data}catch(e){error.value=apiMessage(e)}finally{loading.value=false}}; onMounted(load);
</script>
<template><PageHeading eyebrow="Performance management" title="State Performance Ranking"><span class="civic-kicker">Achievement ranking · verified reports only</span></PageHeading><div v-if="error" class="civic-error">{{error}}</div><section class="civic-workspace"><div class="civic-form-grid"><label class="civic-field"><span>Year</span><input v-model="year" type="number"></label><label class="civic-field"><span>Period</span><select v-model="period"><option v-for="value in ['q1','q2','q3','q4','annual']" :key="value" :value="value">{{value.toUpperCase()}}</option></select></label><div class="civic-field"><span>&nbsp;</span><button class="civic-button civic-button-primary" :disabled="loading" @click="load">Apply</button></div></div><p v-if="data">Rank eligibility requires {{percent(data.minimum_reporting_completeness)}} reporting completeness. Completeness, evidence, and expenditure do not change achievement rank.</p></section><LoadingBlock v-if="loading"/><section v-else-if="data" class="civic-workspace"><div class="civic-table-wrap"><table class="civic-table"><thead><tr><th>Rank</th><th>MDA</th><th>Achievement</th><th>Completeness</th><th>Evidence</th><th>Financial execution</th><th>Status</th></tr></thead><tbody><tr v-for="mda in data.mdas" :key="mda.id"><td>{{mda.rank ?? '—'}}</td><td><RouterLink :to="{path:'/workplan-performance',query:{workplan_id:mda.workplan_id,period:data.period}}">{{mda.name}}</RouterLink><br><small>Revision {{mda.revision_no}}</small></td><td>{{percent(mda.official_score)}}</td><td>{{percent(mda.reporting_completeness.ratio)}}</td><td>{{percent(mda.evidence_coverage.ratio)}}</td><td>{{percent(mda.financial_execution.ratio)}}</td><td>{{mda.rank_status.replace('_',' ')}}</td></tr><tr v-if="!data.mdas.length"><td colspan="7">No eligible Workplan data for this period.</td></tr></tbody></table></div></section></template>
